import itertools

def has_path(n, edges):
    edge_set=set(frozenset(e) for e in edges)
    for perm in itertools.permutations(range(n)):
        ok=True
        for i in range(n-1):
            if frozenset((perm[i],perm[i+1])) not in edge_set:
                ok=False; break
        if ok:
